CREATE TEMP TABLE agama_matches_20260910 ON COMMIT DROP AS
SELECT r.no,r.nama,r.kelas,r.agama,
  count(s.id) AS jumlah_cocok,
  (array_agg(s.id) FILTER (WHERE s.id IS NOT NULL))[1] AS student_id
FROM agama_source_20260910 r
LEFT JOIN public.students s
  ON lower(regexp_replace(btrim(s.nama),'\s+',' ','g')) = lower(regexp_replace(btrim(r.nama),'\s+',' ','g'))
  AND (r.kelas IS NULL OR EXISTS (SELECT 1 FROM public.classes c
    WHERE c.id=s.kelas_id AND lower(regexp_replace(btrim(c.nama),'\s+',' ','g')) = lower(regexp_replace(btrim(r.kelas),'\s+',' ','g'))))
GROUP BY r.no,r.nama,r.kelas,r.agama;

-- Stop conflicting source matches from targeting the same database student.
CREATE TEMP TABLE agama_result_20260910 ON COMMIT DROP AS
SELECT m.*,CASE
  WHEN jumlah_cocok=0 THEN 'TIDAK DITEMUKAN: periksa nama / kelas'
  WHEN jumlah_cocok>1 THEN 'AMBIGU: beberapa siswa cocok'
  WHEN (SELECT count(*) FROM agama_matches_20260910 x WHERE x.student_id=m.student_id AND x.jumlah_cocok=1)>1 THEN 'AMBIGU: sumber ganda'
  WHEN nullif(btrim(s.agama),'') IS NULL THEN 'DIISI'
  WHEN s.agama=m.agama THEN 'SUDAH SESUAI'
  ELSE 'KONFLIK: periksa agama yang sudah ada'
END AS hasil
FROM agama_matches_20260910 m LEFT JOIN public.students s ON s.id=m.student_id;

INSERT INTO mitrarsq_private.agama_backup_20260910(student_id,agama_sebelum,agama_import)
SELECT s.id,s.agama,r.agama FROM agama_result_20260910 r JOIN public.students s ON s.id=r.student_id
WHERE r.hasil='DIISI' ON CONFLICT (student_id) DO NOTHING;

UPDATE public.students s SET agama=r.agama FROM agama_result_20260910 r
WHERE r.student_id=s.id AND r.hasil='DIISI';

-- Hasil per siswa; filter baris selain DIISI / SUDAH SESUAI untuk pemeriksaan manual.
SELECT no,nama,kelas,agama,hasil FROM agama_result_20260910 ORDER BY hasil,no;
COMMIT;
